:root{
      --bg:#060b13;
      --bg-soft:#0b1422;
      --surface:#101c2d;
      --surface-2:#15253a;
      --text:#f8fafc;
      --muted:#a6b3c3;
      --line:rgba(255,255,255,.10);
      --gold:#f2b84b;
      --gold-2:#ffd47a;
      --steel:#8ec5db;
      --green:#35d07f;
      --shadow:0 28px 80px rgba(0,0,0,.38);
      --radius:26px;
      --container:min(1180px,92%);
    }

    *{box-sizing:border-box;margin:0;padding:0}
    html{scroll-behavior:smooth}
    body{
      font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;
      color:var(--text);
      background:
        radial-gradient(circle at 15% 15%,rgba(142,197,219,.09),transparent 30%),
        radial-gradient(circle at 85% 20%,rgba(242,184,75,.08),transparent 30%),
        var(--bg);
      line-height:1.65;
      overflow-x:hidden;
    }

    body::before{
      content:"";
      position:fixed;
      inset:0;
      pointer-events:none;
      z-index:-2;
      background-image:
        linear-gradient(rgba(255,255,255,.018) 1px,transparent 1px),
        linear-gradient(90deg,rgba(255,255,255,.018) 1px,transparent 1px);
      background-size:50px 50px;
      mask-image:linear-gradient(to bottom,black,transparent 85%);
    }

    img{display:block;max-width:100%}
    a{color:inherit;text-decoration:none}
    button,input,textarea,select{font:inherit}
    .container{width:var(--container);margin:auto}

    .topbar{
      position:fixed;
      inset:0 0 auto;
      z-index:1000;
      transition:.3s ease;
    }

    .topbar.scrolled{
      background:rgba(6,11,19,.90);
      backdrop-filter:blur(18px);
      border-bottom:1px solid var(--line);
      box-shadow:0 15px 42px rgba(0,0,0,.25);
    }

    .nav{
      min-height:80px;
      display:flex;
      align-items:center;
      justify-content:space-between;
      gap:24px;
    }

    .brand{
      display:flex;
      align-items:center;
      gap:12px;
      font-weight:850;
      letter-spacing:.04em;
    }

    .brand-mark{
      width:46px;height:46px;
      display:grid;place-items:center;
      border-radius:14px;
      color:#111827;
      background:linear-gradient(135deg,var(--gold),var(--gold-2));
      box-shadow:0 14px 30px rgba(242,184,75,.24);
      font-size:.86rem;
    }

    .brand small{display:block;color:var(--muted);font-size:.68rem;font-weight:600;letter-spacing:.08em}

    .nav-links{
      display:flex;
      align-items:center;
      gap:27px;
      color:#d8e1eb;
      font-size:.93rem;
    }

    .nav-links a{position:relative}
    .nav-links a::after{
      content:"";
      position:absolute;
      left:0;right:0;bottom:-8px;
      height:2px;
      background:var(--gold);
      transform:scaleX(0);
      transition:.25s ease;
    }
    .nav-links a:hover::after{transform:scaleX(1)}

    .btn,.nav-cta{
      min-height:50px;
      display:inline-flex;
      align-items:center;
      justify-content:center;
      gap:9px;
      padding:0 22px;
      border-radius:14px;
      border:0;
      cursor:pointer;
      font-weight:800;
      transition:.25s ease;
    }

    .btn-primary,.nav-cta{
      color:#151b24;
      background:linear-gradient(135deg,var(--gold),var(--gold-2));
      box-shadow:0 16px 32px rgba(242,184,75,.20);
    }

    .btn-secondary{
      color:white;
      background:rgba(255,255,255,.04);
      border:1px solid var(--line);
      backdrop-filter:blur(12px);
    }

    .btn:hover,.nav-cta:hover{transform:translateY(-3px)}

    .menu-toggle{
      display:none;
      width:45px;height:45px;
      border-radius:13px;
      border:1px solid var(--line);
      background:rgba(255,255,255,.04);
      color:white;
      cursor:pointer;
      font-size:1.25rem;
    }

    .hero{
      min-height:100svh;
      display:grid;
      align-items:center;
      padding:130px 0 80px;
      position:relative;
      isolation:isolate;
      overflow:hidden;
    }

    .hero::before{
      content:"";
      position:absolute;
      inset:0;
      z-index:-2;
      background:
        linear-gradient(90deg,rgba(5,10,18,.97) 0%,rgba(5,10,18,.84) 45%,rgba(5,10,18,.42) 74%,rgba(5,10,18,.74) 100%),
        url("data:image/webp;base64,") center/cover no-repeat;
      filter:saturate(.82) contrast(1.05);
    }

    .hero::after{
      content:"";
      position:absolute;
      inset:auto 0 0;
      height:180px;
      z-index:-1;
      background:linear-gradient(transparent,var(--bg));
    }

    .hero-content{max-width:780px}

    .eyebrow{
      display:inline-flex;
      align-items:center;
      gap:9px;
      padding:8px 13px;
      border-radius:999px;
      border:1px solid rgba(242,184,75,.28);
      background:rgba(242,184,75,.08);
      color:var(--gold-2);
      font-size:.78rem;
      font-weight:850;
      letter-spacing:.13em;
      text-transform:uppercase;
    }

    .eyebrow-dot{
      width:8px;height:8px;border-radius:50%;
      background:var(--green);
      box-shadow:0 0 0 6px rgba(53,208,127,.10);
    }

    h1{
      margin:25px 0 22px;
      max-width:850px;
      font-size:clamp(3.25rem,8vw,6.8rem);
      line-height:.92;
      letter-spacing:-.065em;
    }

    h1 span{
      background:linear-gradient(90deg,#fff,var(--gold-2));
      -webkit-background-clip:text;
      background-clip:text;
      color:transparent;
    }

    .hero p{
      max-width:700px;
      color:#c4cfdb;
      font-size:clamp(1rem,1.6vw,1.18rem);
    }

    .hero-actions{display:flex;flex-wrap:wrap;gap:14px;margin-top:34px}

    .hero-points{
      display:grid;
      grid-template-columns:repeat(3,minmax(0,1fr));
      gap:14px;
      margin-top:50px;
      max-width:750px;
    }

    .hero-point{
      padding:16px 17px;
      border:1px solid var(--line);
      border-radius:17px;
      background:rgba(10,19,32,.60);
      backdrop-filter:blur(12px);
    }
    .hero-point strong{display:block;font-size:1rem}
    .hero-point span{font-size:.82rem;color:var(--muted)}

    section{padding:105px 0}

    .section-head{
      display:flex;
      align-items:end;
      justify-content:space-between;
      gap:40px;
      margin-bottom:48px;
    }

    .section-head h2{
      max-width:730px;
      margin-top:17px;
      font-size:clamp(2.25rem,5vw,4.3rem);
      line-height:1;
      letter-spacing:-.05em;
    }

    .section-head p{max-width:490px;color:var(--muted)}

    .services{
      display:grid;
      grid-template-columns:repeat(4,minmax(0,1fr));
      gap:20px;
    }

    .service{
      min-height:330px;
      padding:28px;
      border-radius:var(--radius);
      border:1px solid var(--line);
      background:linear-gradient(145deg,rgba(21,37,58,.90),rgba(9,18,31,.94));
      box-shadow:0 22px 65px rgba(0,0,0,.17);
      transition:.3s ease;
      position:relative;
      overflow:hidden;
    }

    .service:hover{transform:translateY(-9px);border-color:rgba(242,184,75,.38)}

    .service::after{
      content:"";
      position:absolute;
      width:170px;height:170px;
      right:-70px;bottom:-80px;
      border-radius:50%;
      background:radial-gradient(circle,rgba(242,184,75,.16),transparent 70%);
    }

    .service-icon{
      width:60px;height:60px;
      display:grid;place-items:center;
      border-radius:18px;
      margin-bottom:72px;
      font-size:1.65rem;
      background:rgba(242,184,75,.10);
      border:1px solid rgba(242,184,75,.16);
    }

    .service h3{font-size:1.3rem;margin-bottom:11px}
    .service p{color:var(--muted)}

    .about{
      display:grid;
      grid-template-columns:.95fr 1.05fr;
      gap:45px;
      align-items:center;
    }

    .about-image{
      min-height:540px;
      border-radius:30px;
      overflow:hidden;
      position:relative;
      border:1px solid var(--line);
      box-shadow:var(--shadow);
      background:url("data:image/webp;base64,") center/cover no-repeat;
    }

    .about-image::after{
      content:"Trabajo serio. Resultados duraderos.";
      position:absolute;
      left:24px;right:24px;bottom:24px;
      padding:20px;
      border-radius:18px;
      background:rgba(5,11,19,.78);
      backdrop-filter:blur(14px);
      border:1px solid var(--line);
      font-weight:800;
    }

    .about-copy{
      padding:38px;
      border-radius:30px;
      border:1px solid var(--line);
      background:linear-gradient(145deg,rgba(21,37,58,.72),rgba(9,18,31,.85));
    }

    .about-copy h2{
      margin:18px 0;
      font-size:clamp(2.2rem,5vw,4rem);
      line-height:1;
      letter-spacing:-.05em;
    }
    .about-copy p{color:var(--muted);margin-bottom:16px}

    .values{display:grid;gap:12px;margin-top:25px}
    .value{
      display:flex;
      gap:13px;
      align-items:flex-start;
      padding:14px 0;
      border-bottom:1px solid var(--line);
    }
    .check{
      width:25px;height:25px;
      flex:0 0 auto;
      display:grid;place-items:center;
      border-radius:50%;
      background:var(--green);
      color:#032014;
      font-weight:900;
    }

    .gallery{
      display:grid;
      grid-template-columns:repeat(3,minmax(0,1fr));
      gap:22px;
    }

    .work{
      aspect-ratio:4 / 3;
      border-radius:24px;
      overflow:hidden;
      border:1px solid var(--line);
      position:relative;
      background:#0d1928;
      box-shadow:0 18px 48px rgba(0,0,0,.18);
    }

    .work img{
      width:100%;
      height:100%;
      display:block;
      object-fit:cover;
      object-position:center;
      transition:transform .35s ease;
    }

    .work:hover img{transform:scale(1.04)}
    .work::after{
      content:attr(data-label);
      position:absolute;
      left:14px;right:14px;bottom:14px;
      padding:12px 14px;
      border-radius:14px;
      background:rgba(5,11,19,.76);
      backdrop-filter:blur(12px);
      font-weight:750;
    }
    .process{
      display:grid;
      grid-template-columns:repeat(4,1fr);
      gap:18px;
      counter-reset:steps;
    }

    .step{
      padding:28px;
      border-radius:22px;
      border:1px solid var(--line);
      background:rgba(255,255,255,.03);
      counter-increment:steps;
    }
    .step::before{
      content:"0" counter(steps);
      display:block;
      color:var(--gold);
      font-weight:900;
      margin-bottom:42px;
      font-size:1.1rem;
    }
    .step h3{margin-bottom:10px}
    .step p{color:var(--muted)}

    .contact{
      display:grid;
      grid-template-columns:.9fr 1.1fr;
      gap:28px;
      align-items:stretch;
    }

    .contact-info,.contact-form{
      padding:38px;
      border-radius:30px;
      border:1px solid var(--line);
      background:linear-gradient(145deg,rgba(21,37,58,.80),rgba(9,18,31,.92));
      box-shadow:var(--shadow);
    }

    .contact-info h2{
      margin:18px 0;
      font-size:clamp(2.2rem,4.8vw,4rem);
      line-height:1;
      letter-spacing:-.05em;
    }
    .contact-info>p{color:var(--muted)}
    .contact-list{display:grid;gap:14px;margin-top:30px}
    .contact-item{
      padding:16px;
      border-radius:16px;
      border:1px solid var(--line);
      background:rgba(255,255,255,.025);
    }
    .contact-item strong{display:block;color:var(--gold-2)}

    .form-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}
    .field{display:grid;gap:7px}
    .field.full{grid-column:1/-1}
    label{font-size:.84rem;color:#cdd7e2;font-weight:700}
    input,textarea,select{
      width:100%;
      border:1px solid var(--line);
      border-radius:14px;
      padding:14px 15px;
      color:white;
      background:rgba(255,255,255,.035);
      outline:none;
      transition:.2s ease;
    }
    input:focus,textarea:focus,select:focus{border-color:var(--gold);box-shadow:0 0 0 4px rgba(242,184,75,.10)}
    textarea{min-height:135px;resize:vertical}
    option{color:#111827}

    footer{
      padding:35px 0;
      border-top:1px solid var(--line);
      color:var(--muted);
    }
    .footer-row{display:flex;justify-content:space-between;gap:25px;align-items:center}

    .whatsapp{
      position:fixed;
      right:22px;bottom:22px;
      z-index:900;
      width:58px;height:58px;
      display:grid;place-items:center;
      border-radius:50%;
      background:#24d366;
      color:#052313;
      font-size:1.6rem;
      font-weight:900;
      box-shadow:0 18px 40px rgba(0,0,0,.30);
      transition:.25s ease;
    }
    .whatsapp:hover{transform:translateY(-4px) scale(1.04)}

    .reveal{opacity:0;transform:translateY(22px);transition:.7s ease}
    .reveal.visible{opacity:1;transform:none}

    @media(max-width:980px){
      .services{grid-template-columns:repeat(2,1fr)}
      .gallery{grid-template-columns:repeat(2,minmax(0,1fr))}
      .about,.contact{grid-template-columns:1fr}
      .process{grid-template-columns:repeat(2,1fr)}
      .section-head{display:block}
      .section-head p{margin-top:18px}
    }

    @media(max-width:760px){
      .menu-toggle{display:grid;place-items:center}
      .nav-cta{display:none}
      .nav-links{
        position:fixed;
        top:76px;left:4%;right:4%;
        display:grid;
        gap:7px;
        padding:18px;
        border-radius:18px;
        border:1px solid var(--line);
        background:rgba(6,11,19,.97);
        backdrop-filter:blur(16px);
        opacity:0;
        transform:translateY(-14px);
        pointer-events:none;
        transition:.25s ease;
      }
      .nav-links.open{opacity:1;transform:none;pointer-events:auto}
      .hero{padding-top:120px}
      .hero-points{grid-template-columns:1fr}
      .gallery{display:grid;grid-template-columns:1fr;gap:18px}
      .work{aspect-ratio:4 / 3}
      .form-grid{grid-template-columns:1fr}
      .field.full{grid-column:auto}
      section{padding:80px 0}
      .footer-row{display:block}
      .footer-row p{margin-top:15px}
    }

    @media(max-width:520px){
      h1{font-size:3.25rem}
      .hero-actions{display:grid}
      .btn{width:100%}
      .services,.process{grid-template-columns:1fr}
      .service{min-height:auto}
      .service-icon{margin-bottom:42px}
      .about-image{min-height:360px}
      .about-copy,.contact-info,.contact-form{padding:26px 20px}
      .whatsapp{right:15px;bottom:15px}
    }

    @media(prefers-reduced-motion:reduce){
      *,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}
    }
  
    .work img:not([src]), .work img[src=""]{
      display:none;
    }
    .work{
      background:
        linear-gradient(135deg,rgba(242,184,75,.10),rgba(142,197,219,.08)),
        #132033;
    }

  

    /* Juego de memoria corregido */
    .memory-section{
      background:
        radial-gradient(circle at 20% 15%,rgba(242,184,75,.08),transparent 30%),
        linear-gradient(180deg,transparent,rgba(255,255,255,.018));
    }

    .memory-wrapper{
      padding:34px;
      border:1px solid var(--line);
      border-radius:30px;
      background:linear-gradient(145deg,rgba(21,37,58,.82),rgba(9,18,31,.94));
      box-shadow:var(--shadow);
    }

    .memory-top{
      display:flex;
      justify-content:space-between;
      align-items:center;
      gap:18px;
      margin-bottom:28px;
    }

    .memory-stats{
      display:flex;
      flex-wrap:wrap;
      gap:12px;
    }

    .memory-stat{
      min-width:125px;
      padding:13px 16px;
      border-radius:15px;
      border:1px solid var(--line);
      background:rgba(255,255,255,.04);
    }

    .memory-stat span{
      display:block;
      color:var(--muted);
      font-size:.76rem;
      text-transform:uppercase;
      letter-spacing:.08em;
    }

    .memory-stat strong{
      display:block;
      font-size:1.35rem;
      color:var(--gold-2);
    }

    .memory-grid{
      width:min(760px,100%);
      margin:0 auto;
      display:grid;
      grid-template-columns:repeat(4,1fr);
      gap:14px;
    }

    .memory-card{
      width:100%;
      aspect-ratio:1/1;
      min-height:125px;
      border:1px solid rgba(242,184,75,.28);
      border-radius:19px;
      color:#151b24;
      background:
        linear-gradient(145deg,rgba(255,255,255,.28),transparent 44%),
        linear-gradient(135deg,var(--gold),var(--gold-2));
      box-shadow:0 15px 34px rgba(0,0,0,.22);
      cursor:pointer;
      display:grid;
      place-items:center;
      font-weight:950;
      font-size:clamp(1.15rem,2.5vw,1.65rem);
      transition:transform .2s ease,background .25s ease,border-color .25s ease;
      user-select:none;
      -webkit-tap-highlight-color:transparent;
    }

    .memory-card:hover{
      transform:translateY(-4px);
    }

    .memory-card.flipped,
    .memory-card.matched{
      color:white;
      background:linear-gradient(145deg,#25415f,#101d30);
      font-size:clamp(2rem,5vw,3.4rem);
      border-color:rgba(242,184,75,.45);
    }

    .memory-card.matched{
      background:linear-gradient(145deg,rgba(53,208,127,.32),#102b24);
      border-color:rgba(53,208,127,.70);
      box-shadow:0 0 0 3px rgba(53,208,127,.10);
    }

    .memory-card:disabled{
      cursor:default;
      opacity:1;
    }

    .memory-message{
      min-height:28px;
      margin-top:23px;
      text-align:center;
      color:var(--gold-2);
      font-weight:800;
    }

    @media(max-width:760px){
      .memory-top{display:block}
      .memory-stats{margin:18px 0}
      .memory-wrapper{padding:24px 16px}
      .memory-grid{grid-template-columns:repeat(3,1fr);gap:10px}
      .memory-card{min-height:100px}
    }

    @media(max-width:430px){
      .memory-grid{grid-template-columns:repeat(3,1fr);gap:8px}
      .memory-card{min-height:86px;border-radius:15px}
      .memory-stat{min-width:calc(50% - 6px)}
    }


/* Cambio de modo día / noche */
.theme-toggle{
  width:45px;
  height:45px;
  display:grid;
  place-items:center;
  flex:0 0 auto;
  border-radius:13px;
  border:1px solid var(--line);
  background:rgba(255,255,255,.06);
  color:var(--text);
  cursor:pointer;
  font-size:1.15rem;
  transition:.25s ease;
}
.theme-toggle:hover{transform:translateY(-2px)}

body.light-mode{
  --bg:#f4f7fb;
  --bg-soft:#eef3f8;
  --surface:#ffffff;
  --surface-2:#e9f0f7;
  --text:#172033;
  --muted:#5f6f82;
  --line:rgba(18,32,51,.14);
  --shadow:0 28px 80px rgba(30,48,72,.14);
  background:
    radial-gradient(circle at 15% 15%,rgba(142,197,219,.18),transparent 30%),
    radial-gradient(circle at 85% 20%,rgba(242,184,75,.16),transparent 30%),
    var(--bg);
}
body.light-mode::before{
  background-image:
    linear-gradient(rgba(18,32,51,.035) 1px,transparent 1px),
    linear-gradient(90deg,rgba(18,32,51,.035) 1px,transparent 1px);
}
body.light-mode .topbar.scrolled{
  background:rgba(244,247,251,.92);
  box-shadow:0 15px 42px rgba(30,48,72,.12);
}
body.light-mode .nav-links{color:#34445a}
body.light-mode .menu-toggle,
body.light-mode .theme-toggle{
  background:rgba(255,255,255,.75);
  color:#172033;
}
body.light-mode .btn-secondary{color:#172033;background:rgba(255,255,255,.72)}
body.light-mode .hero h1,
body.light-mode .hero p,
body.light-mode .hero .eyebrow,
body.light-mode .hero .hero-note{color:var(--text)}
body.light-mode footer{color:var(--text)}

@media(max-width:900px){
  .theme-toggle{margin-left:auto}
}

/* ===== MODO DÍA MEJORADO: estilo claro uniforme ===== */
body.light-mode .topbar,
body.light-mode .topbar.scrolled{
  background:rgba(247,249,252,.96);
  border-bottom:1px solid var(--line);
  backdrop-filter:blur(18px);
}
body.light-mode .brand,
body.light-mode .nav-links,
body.light-mode .nav-links a{color:var(--text)}
body.light-mode .hero-point,
body.light-mode .service,
body.light-mode .about-copy,
body.light-mode .step,
body.light-mode .contact-info,
body.light-mode .contact-form,
body.light-mode .contact-item,
body.light-mode .memory-wrapper,
body.light-mode .memory-stat{
  background:rgba(255,255,255,.72);
  color:var(--text);
  border-color:rgba(18,32,51,.14);
  box-shadow:none;
}
body.light-mode .service p,
body.light-mode .about-copy p,
body.light-mode .step p,
body.light-mode .contact-info p,
body.light-mode .contact-item,
body.light-mode .memory-stat span{color:var(--muted)}
body.light-mode .gallery-item{background:#eef3f8;border-color:var(--line);box-shadow:none}
body.light-mode input,
body.light-mode textarea,
body.light-mode select{
  color:var(--text);
  background:#fff;
  border-color:var(--line);
}
body.light-mode input::placeholder,
body.light-mode textarea::placeholder{color:#7b8898}
body.light-mode .memory-section{
  background:linear-gradient(180deg,transparent,rgba(18,32,51,.015));
}
body.light-mode .memory-card.flipped{
  color:#172033;
  background:#fff;
  border-color:rgba(242,184,75,.55);
}
body.light-mode .memory-card.matched{
  color:#172033;
  background:#e8f8ef;
  border-color:rgba(53,208,127,.55);
}
body.light-mode footer{background:#eef3f8}
body.light-mode .about-image::after,
body.light-mode .gallery-item span{
  color:#fff;
  border-color:rgba(255,255,255,.18);
}

/* =========================================================
   AJUSTES FINALES DE MODO DÍA / NOCHE
   Corrige Inicio y Trabajos para mantener buen contraste
   ========================================================= */

/* ---------- MODO NOCHE ---------- */
body:not(.light-mode) .hero h1{color:#f8fafc}
body:not(.light-mode) .hero h1 span{
  background:linear-gradient(90deg,#ffffff,var(--gold-2));
  -webkit-background-clip:text;
  background-clip:text;
  color:transparent;
}
body:not(.light-mode) .hero p{color:#c4cfdb}
body:not(.light-mode) .hero-point{
  color:#f8fafc;
  background:rgba(10,19,32,.68);
  border-color:rgba(255,255,255,.12);
}
body:not(.light-mode) .hero-point span{color:#aebdcd}

body:not(.light-mode) .work::after{
  color:#f8fafc;
  background:rgba(5,11,19,.82);
  border:1px solid rgba(255,255,255,.10);
  box-shadow:0 10px 28px rgba(0,0,0,.20);
}

/* ---------- MODO DÍA ---------- */
body.light-mode .hero::before{
  /* La imagen sigue visible, pero con una capa clara para que el texto se lea */
  filter:saturate(.78) contrast(.92) brightness(1.04);
}

body.light-mode .hero::after{
  height:230px;
  background:linear-gradient(transparent,var(--bg));
}

/* Capa clara adicional sobre la foto en modo día */
body.light-mode .hero{
  background:transparent;
}
body.light-mode .hero .container{
  position:relative;
  z-index:2;
}
body.light-mode .hero::before{
  opacity:1;
}
body.light-mode .hero::after{
  z-index:-1;
}

/* El pseudo-elemento original contiene la foto. Añadimos una capa clara encima */
body.light-mode .hero-content{
  position:relative;
}
body.light-mode .hero-content::before{
  content:"";
  position:absolute;
  z-index:-1;
  top:-70px;
  left:-70px;
  width:min(900px,calc(100vw - 28px));
  height:calc(100% + 140px);
  border-radius:36px;
  background:linear-gradient(90deg,
    rgba(247,249,252,.96) 0%,
    rgba(247,249,252,.91) 60%,
    rgba(247,249,252,.72) 82%,
    rgba(247,249,252,.18) 100%);
  box-shadow:0 30px 80px rgba(30,48,72,.08);
  pointer-events:none;
}

body.light-mode .hero h1{
  color:#172033 !important;
  text-shadow:none;
}
body.light-mode .hero h1 span{
  background:linear-gradient(90deg,#172033,#c88613 78%);
  -webkit-background-clip:text;
  background-clip:text;
  color:transparent !important;
}
body.light-mode .hero p{
  color:#53657a !important;
}
body.light-mode .hero .eyebrow{
  color:#8d620d !important;
  background:rgba(242,184,75,.13);
  border-color:rgba(199,137,26,.34);
}
body.light-mode .hero-point{
  background:rgba(255,255,255,.84) !important;
  border-color:rgba(18,32,51,.13) !important;
  box-shadow:0 12px 32px rgba(30,48,72,.07) !important;
  color:#172033 !important;
}
body.light-mode .hero-point strong{color:#172033}
body.light-mode .hero-point span{color:#607187 !important}
body.light-mode .hero .btn-secondary{
  color:#172033;
  background:rgba(255,255,255,.88);
  border-color:rgba(18,32,51,.14);
}

/* Galería: etiquetas claras y legibles durante el día */
body.light-mode .work{
  background:#ffffff;
  border-color:rgba(18,32,51,.15);
  box-shadow:0 16px 38px rgba(30,48,72,.10);
}
body.light-mode .work::after{
  color:#172033;
  background:rgba(255,255,255,.91);
  border:1px solid rgba(18,32,51,.12);
  box-shadow:0 8px 24px rgba(30,48,72,.10);
  backdrop-filter:blur(14px);
}
body.light-mode .work img{
  filter:saturate(.96) contrast(.98) brightness(1.02);
}
body:not(.light-mode) .work img{
  filter:saturate(.90) contrast(1.03) brightness(.92);
}

/* Quiénes somos: limpio en día, sólido en noche */
body.light-mode .about-copy{
  background:rgba(255,255,255,.86) !important;
  color:#172033;
  border-color:rgba(18,32,51,.13) !important;
  box-shadow:0 18px 46px rgba(30,48,72,.08) !important;
}
body.light-mode .about-image::after{
  color:#172033;
  background:rgba(255,255,255,.90);
  border-color:rgba(18,32,51,.12);
}
body:not(.light-mode) .about-image::after{color:#f8fafc}

/* Transiciones suaves al cambiar el tema */
body,
.topbar,
.hero,
.hero::before,
.hero-content::before,
.service,
.about-copy,
.step,
.work,
.work::after,
.contact-info,
.contact-form,
.memory-wrapper,
.memory-card,
footer{
  transition:background-color .28s ease,border-color .28s ease,color .28s ease,box-shadow .28s ease,filter .28s ease,opacity .28s ease;
}

/* Ajustes responsive del bloque claro del hero */
@media(max-width:900px){
  body.light-mode .hero-content::before{
    top:-45px;
    left:-24px;
    width:calc(100% + 48px);
    height:calc(100% + 90px);
    border-radius:28px;
    background:rgba(247,249,252,.91);
  }
}

@media(max-width:600px){
  body.light-mode .hero-content::before{
    top:-28px;
    left:-14px;
    width:calc(100% + 28px);
    height:calc(100% + 56px);
    border-radius:22px;
    background:rgba(247,249,252,.93);
  }
  body.light-mode .work::after,
  body:not(.light-mode) .work::after{
    left:10px;
    right:10px;
    bottom:10px;
    padding:11px 12px;
  }
}


/* =========================================================
   AJUSTE VISUAL PRO - PORTADA DÍA / NOCHE
   ========================================================= */

/* Evita el panel blanco grande que partía visualmente la portada */
body.light-mode .hero-content::before{display:none !important;content:none !important;}

/* PORTADA EN MODO DÍA: imagen limpia con degradado suave */
body.light-mode .hero{
  min-height:calc(100svh - 80px);
  padding:145px 0 90px;
  background:#f7f9fc !important;
}
body.light-mode .hero::before{
  opacity:1 !important;
  filter:none !important;
  background:
    linear-gradient(90deg,
      rgba(247,249,252,.99) 0%,
      rgba(247,249,252,.97) 34%,
      rgba(247,249,252,.88) 50%,
      rgba(247,249,252,.58) 67%,
      rgba(247,249,252,.22) 84%,
      rgba(247,249,252,.08) 100%),
    url("data:image/webp;base64,") center/cover no-repeat !important;
}
body.light-mode .hero::after{
  height:160px !important;
  background:linear-gradient(transparent,#f7f9fc) !important;
}
body.light-mode .hero-content{
  max-width:720px !important;
  padding:0 !important;
  background:transparent !important;
  box-shadow:none !important;
}
body.light-mode .hero h1{
  max-width:690px;
  margin-top:22px;
  color:#172033 !important;
  text-shadow:none !important;
}
body.light-mode .hero h1 span{
  background:linear-gradient(90deg,#172033 0%,#b77708 72%,#d99212 100%) !important;
  -webkit-background-clip:text !important;
  background-clip:text !important;
  color:transparent !important;
}
body.light-mode .hero p{
  max-width:690px;
  color:#52657a !important;
  font-weight:500;
}
body.light-mode .hero .eyebrow{
  color:#7d570c !important;
  background:rgba(255,255,255,.76) !important;
  border-color:rgba(199,137,26,.30) !important;
  box-shadow:0 8px 24px rgba(30,48,72,.06);
}

/* PORTADA EN MODO NOCHE: contraste alto sin oscurecer demasiado la foto */
body:not(.light-mode) .hero::before{
  filter:none !important;
  background:
    linear-gradient(90deg,
      rgba(5,10,18,.96) 0%,
      rgba(5,10,18,.90) 36%,
      rgba(5,10,18,.70) 56%,
      rgba(5,10,18,.34) 78%,
      rgba(5,10,18,.24) 100%),
    url("data:image/webp;base64,") center/cover no-repeat !important;
}
body:not(.light-mode) .hero-content{max-width:720px;}
body:not(.light-mode) .hero h1{text-shadow:0 3px 22px rgba(0,0,0,.28);}
body:not(.light-mode) .hero p{color:#d2dbe5 !important;}

/* Tarjetas pequeñas de la portada */
body.light-mode .hero-point{
  background:rgba(255,255,255,.82) !important;
  border:1px solid rgba(18,32,51,.12) !important;
  box-shadow:0 12px 30px rgba(31,49,74,.07) !important;
}
body:not(.light-mode) .hero-point{
  background:rgba(8,16,28,.62) !important;
  border:1px solid rgba(255,255,255,.11) !important;
  backdrop-filter:blur(10px);
}

/* TRABAJOS: etiquetas limpias en ambos temas */
body.light-mode .work::after{
  color:#172033 !important;
  background:rgba(255,255,255,.94) !important;
  border:1px solid rgba(18,32,51,.10) !important;
  box-shadow:0 8px 22px rgba(31,49,74,.10) !important;
  backdrop-filter:blur(10px);
}
body:not(.light-mode) .work::after{
  color:#f8fafc !important;
  background:rgba(7,14,24,.84) !important;
  border:1px solid rgba(255,255,255,.12) !important;
  box-shadow:0 8px 22px rgba(0,0,0,.24) !important;
  backdrop-filter:blur(10px);
}

/* Móvil: evita títulos cortados y mantiene la imagen visible */
@media(max-width:700px){
  body.light-mode .hero,
  body:not(.light-mode) .hero{
    min-height:auto;
    padding:118px 0 72px;
  }
  body.light-mode .hero::before{
    background:
      linear-gradient(180deg,
        rgba(247,249,252,.97) 0%,
        rgba(247,249,252,.90) 48%,
        rgba(247,249,252,.64) 100%),
      url("data:image/webp;base64,") center/cover no-repeat !important;
  }
  body:not(.light-mode) .hero::before{
    background:
      linear-gradient(180deg,
        rgba(5,10,18,.92) 0%,
        rgba(5,10,18,.82) 52%,
        rgba(5,10,18,.58) 100%),
      url("data:image/webp;base64,") center/cover no-repeat !important;
  }
  .hero h1{font-size:clamp(3rem,14vw,5.3rem) !important;line-height:.95 !important;}
}


/* =========================================================
   PULIDO FINAL DE PORTADA + MODO DÍA / NOCHE
   ========================================================= */

/* Portada más equilibrada: menos texto gigante y más fotografía */
.hero{
  min-height:calc(100svh - 80px) !important;
  padding:128px 0 72px !important;
}
.hero-content{
  max-width:660px !important;
  position:relative;
  z-index:2;
}
.hero h1{
  font-size:clamp(3.35rem,6vw,6.25rem) !important;
  line-height:.94 !important;
