  max-width:650px;
  margin-top:22px;
}
.hero h1 span{
  display:block;
  margin-top:8px;
  color:#d59000 !important;
  background:none !important;
  -webkit-text-fill-color:currentColor !important;
}
.hero p{
  max-width:620px !important;
  font-size:clamp(1rem,1.25vw,1.12rem) !important;
  line-height:1.72 !important;
  margin-top:24px !important;
}
.hero-actions{margin-top:28px !important;}
.hero-points{margin-top:38px !important;}

/* DÍA: fotografía visible, transición más corta y sin efecto de neblina */
body.light-mode .hero{
  background:#f5f7fa !important;
}
body.light-mode .hero::before{
  opacity:1 !important;
  filter:none !important;
  background:
    linear-gradient(90deg,
      rgba(245,247,250,.99) 0%,
      rgba(245,247,250,.96) 24%,
      rgba(245,247,250,.82) 38%,
      rgba(245,247,250,.46) 51%,
