body.light-mode .hero h1{color:#172033 !important;text-shadow:none !important;}
body.light-mode .hero h1 span{color:#cc8400 !important;}
body.light-mode .hero p{color:#566a83 !important;font-weight:500;}
body.light-mode .hero .eyebrow{
  color:#8b620f !important;
  background:rgba(255,255,255,.76) !important;
  border-color:rgba(204,132,0,.30) !important;
  backdrop-filter:blur(10px);
}
body.light-mode .hero-point{
