  border-color:rgba(28,43,61,.10) !important;
  box-shadow:0 12px 30px rgba(24,39,58,.06) !important;
  backdrop-filter:blur(10px);
}

/* NOCHE: conserva más detalle de la fotografía y mejora contraste */
